package io.github.hectorvent.floci.core.common;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Where each operation's request names the roles it passes, read once from the vendored
 * {@code aws/iam-passed-roles.json}.
 *
 * <p>The file is generated by {@code tools/aws/regen_iam_passed_roles.py} from AWS's Service Reference,
 * which lists {@code iam:PassRole} among an operation's authorized actions with the services the role goes
 * to, and from botocore's model of the request, which gives the members that name a role. Every operation
 * of the namespaces it reads is in it once: with the members to read, as one {@link PassedRoles} reads by
 * hand, or as one whose request names no role it can read. {@code make iam-passed-roles-check} re-derives
 * every member from botocore and {@code make iam-passed-roles-verify} checks every operation against AWS.
 *
 * <p>A missing or malformed resource is a build defect, so loading fails with
 * {@link IllegalStateException} rather than leaving every operation it reads unchecked.
 */
final class PassedRoleMembers {

    static final String RESOURCE_NAME = "aws/iam-passed-roles.json";

    private static final ObjectMapper MAPPER = new ObjectMapper();

    /** One step of a member path: a member, then each element of a list, each value of a map, or one key's value. */
    private static final Pattern STEP = Pattern.compile(
            "([A-Za-z][A-Za-z0-9_]*)(?:\\[([A-Za-z0-9_]*)]|\\{([A-Za-z0-9_]*)})?");

    /** How a member path goes on from a member. */
    enum Into { NONE, LIST, MAP, KEY }

    /**
     * A step of a member path: the member {@code name}, then for {@link Into#LIST} each element, named
     * {@code key} in the Query protocol when its shape names it, for {@link Into#MAP} each value, and for
     * {@link Into#KEY} the value under {@code key}.
     */
    record Step(String name, Into into, String key) {
    }

    /**
     * A member of a request that names a role, the service it is passed to (null when the Service Reference
     * names none) and whether the member takes the role by name as well as by ARN. {@code queryKeys} matches
     * the form parameters the Query protocol sends the member as; null for a member it cannot carry.
     */
    record Member(String path, List<Step> steps, Pattern queryKeys, String passedTo, boolean byName) {
    }

    /** The file: the members of each operation read from it, and the operations read by hand. */
    record Table(Map<String, List<Member>> members, Set<String> byHand, Set<String> notRead,
                 Set<String> namespaces, Set<String> notCovered, Set<String> otherNamespaces) {
    }

    private static final class Holder {
        static final Table TABLE = VendoredResources.read(RESOURCE_NAME, "IAM passed role table",
                PassedRoleMembers::parse);
    }

    private PassedRoleMembers() {
    }

    /** The members a request for {@code action} names its roles in; null when this table does not read it. */
    static List<Member> of(String action) {
        return Holder.TABLE.members().get(action);
    }

    static Table table() {
        return Holder.TABLE;
    }

    static Table parse(InputStream in) throws IOException {
        JsonNode document = MAPPER.readTree(in);
        JsonNode operations = document.path("operations");
        if (!operations.isObject() || operations.isEmpty()) {
            throw new IllegalStateException(RESOURCE_NAME + " carries no operations");
        }
        Map<String, List<Member>> members = new LinkedHashMap<>();
        Set<String> byHand = new LinkedHashSet<>();
        Set<String> notRead = new LinkedHashSet<>();
        operations.properties().forEach(operation -> {
            JsonNode entry = operation.getValue();
            if (entry.has("byHand")) {
                byHand.add(operation.getKey());
            } else if (entry.has("notRead")) {
                notRead.add(operation.getKey());
            } else if (entry.path("roles").isArray() && !entry.path("roles").isEmpty()) {
                List<Member> roles = new ArrayList<>();
                for (JsonNode role : entry.path("roles")) {
                    roles.add(member(operation.getKey(), role));
                }
                members.put(operation.getKey(), List.copyOf(roles));
            } else {
                throw new IllegalStateException(RESOURCE_NAME + " says nothing usable for " + operation.getKey());
            }
        });
        return new Table(Map.copyOf(members), Set.copyOf(byHand), Set.copyOf(notRead),
                Set.copyOf(document.path("namespaces").propertyStream().map(Map.Entry::getKey).toList()),
                Set.copyOf(document.path("notCovered").propertyStream().map(Map.Entry::getKey).toList()),
                Set.copyOf(document.path("otherNamespaces").valueStream().map(JsonNode::asText).toList()));
    }

    private static Member member(String operation, JsonNode role) {
        String path = role.path("member").asText("");
        List<Step> steps = steps(path);
        if (steps == null) {
            throw new IllegalStateException(RESOURCE_NAME + " reads " + operation + " at " + path
                    + ", which is no member path");
        }
        String passedTo = role.hasNonNull("passedTo") ? role.get("passedTo").asText() : null;
        return new Member(path, steps, queryKeys(steps), passedTo, role.path("byName").asBoolean(false));
    }

    /** The steps of a vendored member path; null when {@code path} is none. */
    static List<Step> steps(String path) {
        List<Step> steps = new ArrayList<>();
        for (String step : path.split("\\.", -1)) {
            Matcher matcher = STEP.matcher(step);
            if (!matcher.matches()) {
                return null;
            }
            Into into = matcher.group(2) != null ? Into.LIST : matcher.group(3) == null ? Into.NONE
                    : matcher.group(3).isEmpty() ? Into.MAP : Into.KEY;
            String key = into == Into.LIST ? matcher.group(2) : into == Into.KEY ? matcher.group(3) : null;
            steps.add(new Step(matcher.group(1), into, key));
        }
        return List.copyOf(steps);
    }

    /**
     * The form parameters the Query protocol sends a member as: a list's elements numbered under its name,
     * generically as {@code member.N}, under the name its shape gives them or bare, as {@link AwsQueryLists}
     * reads them, and a map's values as {@code entry.N.value}. A step into one key of a map is not read from a
     * form, whose keys and values are separate parameters.
     */
    private static Pattern queryKeys(List<Step> steps) {
        StringBuilder regex = new StringBuilder();
        for (Step step : steps) {
            if (step.into() == Into.KEY) {
                return null;
            }
            if (!regex.isEmpty()) {
                regex.append("\\.");
            }
            regex.append(Pattern.quote(step.name()));
            if (step.into() == Into.LIST) {
                regex.append(step.key().isEmpty() ? "(\\.member)?" : "(\\.member|\\." + Pattern.quote(step.key()) + ")?")
                        .append("\\.\\d+");
            } else if (step.into() == Into.MAP) {
                regex.append("\\.entry\\.\\d+\\.value");
            }
        }
        return Pattern.compile(regex.toString());
    }
}
